-- Real Search: 1,000 synthetic sample pages across 20 non-technical domains
-- All URLs use reserved .example domains and are intentionally not real websites.
-- Intended for local FULLTEXT / QUERY EXPANSION testing only.
START TRANSACTION;


COMMIT;

-- Verify imported rows
SELECT COUNT(*) AS total_websites FROM websites;

-- Optional: compare standard FULLTEXT and query expansion
SELECT id, title,
       MATCH(title, subtitle, content) AGAINST('coastal' IN NATURAL LANGUAGE MODE) AS score
FROM websites
WHERE MATCH(title, subtitle, content) AGAINST('coastal' IN NATURAL LANGUAGE MODE)
ORDER BY score DESC LIMIT 20;

SELECT id, title,
       MATCH(title, subtitle, content) AGAINST('coastal' IN NATURAL LANGUAGE MODE WITH QUERY EXPANSION) AS score
FROM websites
WHERE MATCH(title, subtitle, content) AGAINST('coastal' IN NATURAL LANGUAGE MODE WITH QUERY EXPANSION)
ORDER BY score DESC LIMIT 20;